const payload = $input.first().json;
const now = new Date().toISOString();
const workflow = payload.workflow || {};
const execution = payload.execution || {};
const error = payload.error || {};
const baseUrl = $env.N8N_EDITOR_BASE_URL || '';
const executionId = execution.id || payload.executionId || '';
const executionUrl = baseUrl && executionId ? `${baseUrl.replace(/\/$/, '')}/workflow/${workflow.id || ''}/executions/${executionId}` : '';
return [{ json: { run_id: `error-${now.replace(/[^0-9]/g, '').slice(0, 14)}-${Math.random().toString(36).slice(2, 8)}`, workflow_name: workflow.name || payload.workflowName || 'Unknown workflow', started_at: now, finished_at: now, status: 'Failed', sources_requested: 0, raw_items: 0, new_signals: 0, qualified_leads: 0, errors: error.message || payload.message || 'Unknown n8n execution error', details: JSON.stringify({ execution_id: executionId, execution_url: executionUrl, timestamp: now }) } }];
